// AudioContext.cpp - 48kHz Native Rate Lock
static float GetSampleRateForAudioContext(bool aIsOffline, float aSampleRate,
                                          bool aShouldResistFingerprinting) {
  if (aIsOffline) {
    return aSampleRate;
  }
  // GORILLA TWEAK: Force 48000Hz native playback to match ALC269 clock rate
  if (StaticPrefs::media_gorilla_hardware_only_mode()) {
    return 48000.0f;
  }
  if (aSampleRate != 0.0) {
    return aSampleRate;
  }
  return static_cast<float>(
      CubebUtils::PreferredSampleRate(aShouldResistFingerprinting));
}

// AudioDestinationNode.cpp - Fast-Tanh Soft Clipper
void DestinationNodeEngine::ProcessBlock(AudioNodeTrack* aTrack, GraphTime aFrom,
                                         const AudioBlock& aInput, AudioBlock* aOutput,
                                         bool* aFinished) override {
  TRACE("DestinationNodeEngine::ProcessBlock");
  *aOutput = aInput;
  aOutput->mVolume *= mVolume;

  // Apply Soft-Limiter to prevent digital hard clipping
  if (!aOutput->IsNull() && StaticPrefs::media_gorilla_hardware_only_mode()) {
    uint32_t channelCount = aOutput->ChannelCount();
    AutoTArray<const float*, 8> channels;
    for (uint32_t c = 0; c < channelCount; ++c) {
      channels.AppendElement(static_cast<const float*>(aOutput->mChannelData[c]));
    }
    float volume = aOutput->mVolume;
    aOutput->AllocateChannels(channelCount);
    for (uint32_t c = 0; c < channelCount; ++c) {
      float* dest = aOutput->ChannelFloatsForWrite(c);
      const float* src = channels[c];
      for (uint32_t i = 0; i < WEBAUDIO_BLOCK_SIZE; ++i) {
        float x = src[i] * volume;
        // Fast approximation of tanh soft-clipper
        if (x > 1.0f) {
          dest[i] = 1.0f;
        } else if (x < -1.0f) {
          dest[i] = -1.0f;
        } else {
          dest[i] = x * (27.0f + x * x) / (27.0f + 9.0f * x * x);
        }
      }
    }
    aOutput->mVolume = 1.0f; // Volume already integrated into samples
  }
}

// deploy.sh lines 79-80 - Audio patch deployment enabled
deploy_file "$SRC/01.MEDIA/AudioContext.cpp" "dom/media/webaudio/AudioContext.cpp"
deploy_file "$SRC/01.MEDIA/AudioDestinationNode.cpp" "dom/media/webaudio/AudioDestinationNode.cpp"

// HttpConnectionUDP.cpp - 4MB UDP Send Buffer
rv = mSocket->SetSendBufferSize(4194304); // 4 MB upload window

// nsHostResolver.cpp - 3s Negative DNS Cache
static const unsigned int NEGATIVE_RECORD_LIFETIME = 3; // seconds

// nsHttpTransaction.cpp - Upload Pacing
const uint32_t kGorillaUploadChunkSize = 256 * 1024; // 256 KB
if (mRequestSize > 10 * 1024 * 1024 && readCount > kGorillaUploadChunkSize) {
  readCount = kGorillaUploadChunkSize;
}

